    logic Q_internal;

    // Synchronous reset is not specified, so Q_internal initializes to 0
    // by default in simulation, but synthesis tools may vary.
    // We explicitly initialize to 0 for synthesis compatibility.
    initial begin
        Q_internal = 1'b0;
