module TopModule (
    input  clk,
    input  reset,
    output shift_ena
);

    // State encoding for the shift register enable FSM
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        SHIFT1 = 2'b01,
        SHIFT2 = 2'b10,
        SHIFT3 = 2'b11
    } state_t;

    state_t current_state, next_state;

    // State register (positive edge triggered, synchronous reset)
    always_ff @(posedge clk) begin
        if (reset)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    // Next-state logic (combinational)
    always_comb begin
        case (current_state)
            IDLE:     next_state = SHIFT1;
            SHIFT1:   next_state = SHIFT2;
            SHIFT2:   next_state = SHIFT3;
            SHIFT3:   next_state = IDLE;
            default:  next_state = IDLE;
        endcase
    end

    // Output logic (Moore machine: output depends only on state)
    // shift_ena is asserted high for exactly 4 clock cycles (from state IDLE through SHIFT3)
    assign shift_ena = (current_state != IDLE);

endmodule

