    input  areset,
    input  x,
    output z
);

    // State encoding: 2 bits
    // 2'b00: IDLE (waiting for reset release)
    // 2'b01: ACCEPTING (shifting in bits)
    // 2'b10: DONE (outputting the complement of the last bit)
    // 2'b11: should not occur
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        ACCEPT = 2'b01,
        DONE   = 2'b10
    } state_t;

    state_t state, next_state;

    // Register to hold the current input bit (LSB first)
    logic [0:0] x_reg;

    // The output z is the 2's complement of the last accepted bit.
    // 2's complement of a single bit b is !b (since -b mod 2 = !b for b in {0,1}).
    // We assign z directly from the registered bit.
    assign z = ~x_reg;

    // State register (positive edge triggered, asynchronous active-high reset)
    always_ff @(posedge clk or posedge areset) begin
        if (areset)
            state <= IDLE;
        else
            state <= next_state;
    end

    // Next-state logic (Moore machine)
    always_comb begin
        case (state)
            IDLE: begin
                // If reset is released, start accepting bits
                if (!areset)
                    next_state = ACCEPT;
                else
                    next_state = IDLE;
            end

            ACCEPT: begin
                // Shift in the new bit
                x_reg <= x;
                // If reset is asserted during this cycle, go back to IDLE
                // (conversion stops when reset is asserted)
                if (areset)
                    next_state = IDLE;
                else
                    next_state = DONE;
            end

            DONE: begin
                // Hold the output for one cycle, then return to IDLE
                // (The output z already reflects the complement of the last bit)
                if (!areset)
                    next_state = IDLE;
                else
                    next_state = IDLE;
            end

            default: next_state = IDLE;
        endcase
    end

