    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        START  = 2'b01,
        DATA   = 2'b10,
        STOP   = 2'b11
    } state_t;

    state_t state, next_state;
    logic [3:0] bit_cnt;   // counts data bits 0..7 (4 bits enough, wrap at 8)
    logic [7:0] shift_reg; // accumulates the received byte (LSB first)

    // -------------------------------------------------
    // Next-state / output logic (combinational)
    // -------------------------------------------------
