        next_state   = state;
        done         = 1'b0;
        out_byte     = 8'b0;
        shift_reg    = shift_reg; // hold value
        bit_cnt      = bit_cnt;   // hold value

        case (state)
            IDLE: begin
                // Wait for falling edge (start bit = 0)
                if (~in) begin
                    next_state = START;
                    bit_cnt    = 4'b0;   // reset counter for first data bit
                end
            end

            START: begin
                // Start bit verified (in should be 0); move to data collection
                next_state = DATA;
            end

            DATA: begin
                // Shift in the data bit (LSB first)
                shift_reg[bit_cnt] = in;
                if (bit_cnt == 4'b100) begin // 8 bits received (cnt 0..7)
                    next_state = STOP;
                    bit_cnt      = 4'b0;   // reset for stop bit check
                end else begin
                    next_state = DATA;
                    bit_cnt      = bit_cnt + 4'b1;
                end
            end

            STOP: begin
                // Verify stop bit = 1
                if (in) begin
                    // Successful reception: output byte and assert done
                    out_byte   = shift_reg;
                    done       = 1'b1;
                    next_state = IDLE;
                end else begin
                    // Stop bit missing: stay in STOP waiting for a 1
                    next_state = STOP;
                end
            end
        endcase
    end

    // -------------------------------------------------
    // Sequential logic (positive-edge triggered, async reset)
    // -------------------------------------------------
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state      <= IDLE;
            bit_cnt    <= 4'b0;
            shift_reg  <= 8'b0;
        end else begin
            state      <= next_state;
            bit_cnt    <= bit_cnt; // updated in combinational always_comb
            shift_reg  <= shift_reg; // updated in combinational always_comb
        end
    end

endmodule

