    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state   <= A;
            // counter holds the number of w=1 seen in the current window
            // We use 2 bits: 0..3
            // We also need to remember if we have already seen two 1's
            // to generate z in the next cycle.
            // We'll decode z from the counter and a "valid" flag.
            // To keep it simple, we keep a 2-bit counter and a
            // one-cycle flag.
            // Actually, we can just keep a 2-bit counter and a
            // flag 'met' that is set when count reaches 2.
            // But 'met' must be cleared when window slides.
            // We'll implement a small state machine for the window.
            // For brevity, we use a 3-bit shift-register to remember
            // the last three w values, and a counter.
            // However, the spec says "Use as few states as possible".
            // We'll keep the minimal counter approach.
            // Let's use a 2-bit counter for 1's count, and a
            // separate flag for "window started".
            // Actually, the simplest robust way:
            // We shift w into a 3-bit register.
            // We count 1's in that register.
            // When count==2, we set a flag for one cycle.
            // But we need to slide the window.
            // We'll just use a 3-bit shift register.
        end else begin
            state <= next_state;
        end
    end

    // We need to remember the last three w values to count 1's.
    // A 3-bit shift register is the smallest way.
    logic [2:0] w_shift; // w_shift[0] is oldest, w_shift[2] is newest

    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            w_shift <= 3'b000;
        end else begin
            // Shift in new w
            w_shift <= {w_shift[1:0], w};
        end
    end

    // Count the number of 1's in the 3-bit window
    // We'll use a small combinational encoder or just add.
    // Since it's only 3 bits, we can use a case or assign.
    logic [1:0] ones_count;
    always_comb begin
        ones_count = 2'b00;
        if (w_shift[0]) ones_count = ones_count + 1;
        if (w_shift[1]) ones_count = ones_count + 1;
        if (w_shift[2]) ones_count = ones_count + 1;
    end

    // z is asserted high in the clock cycle AFTER the window
    // in which exactly two 1's were detected.
    // The window is the three cycles covered by w_shift.
    // After posedge clk, w_shift holds the previous three w's.
    // So if ones_count == 2, then in the NEXT cycle z should be 1.
    // Otherwise z is 0.
