    // In state A: if s == 1, go to B; else stay in A.
    // In state B: we stay in B (the window sliding is handled by the shift register,
    //              and z is generated based on the window).
    // The spec says: "The FSM continues checking w for the next three clock cycles,
    // and so on." This implies we stay in B indefinitely, constantly checking
    // every consecutive three-cycle window.
    always_comb begin
        case (state)
            A: begin
                if (s == 1'b1)
                    next_state = B;
                else
                    next_state = A;
            end
            B: begin
