module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State: bit 2 = direction (0=left, 1=right), bits 1:0 = mode
    // 00=walking left, 01=walking right, 10=falling, 11=digging
    reg [2:0] state, next_state;

    // Output logic (Moore - outputs depend only on state)
    assign walk_left  = (state == 3'b000);
    assign walk_right = (state == 3'b001);
    assign aaah       = (state == 3'b110);
    assign digging    = (state == 3'b111);

    // State register with asynchronous active-high reset
    always @(posedge clk or posedge areset) begin
        if (areset)
            state <= 3'b000;   // reset to walking left
        else
            state <= next_state;
    end

    // Next-state logic
    always @(*) begin
        next_state = state; // default: stay in current state

        case (state[1:0]) // mode part
            2'b00: begin // Walking left on ground
                // Priority: fall > dig > switch direction
                if (!ground) begin
                    // Ground disappeared, start falling (keep direction)
                    next_state = {state[2], 2'b10};
                end else if (dig) begin
                    // Start digging (keep direction)
                    next_state = {state[2], 2'b11};
                end else begin
                    // Check bumps for direction switch
                    if (bump_left && !bump_right) begin
                        // Bumped on left, walk right
                        next_state = {1'b1, 2'b01};
                    end else if (!bump_left && bump_right) begin
                        // Bumped on right, walk left
                        next_state = {1'b0, 2'b00};
                    end else if (bump_left && bump_right) begin
                        // Bumped on both sides, switch from current direction
                        // Currently walking left, so switch to right
                        next_state = {1'b1, 2'b01};
                    end
                    // If neither bumped, stay walking left
                end
            end

            2'b01: begin // Walking right on ground
                if (!ground) begin
                    next_state = {state[2], 2'b10};
                end else if (dig) begin
                    next_state = {state[2], 2'b11};
                end else begin
                    if (bump_left && !bump_right) begin
                        // Bumped on left, walk right (but we're already walking right?)
                        // Actually bump_left should make us walk right, which is same as current
                        next_state = {1'b1, 2'b01};
                    end else if (!bump_left && bump_right) begin
                        // Bumped on right, walk left
                        next_state = {1'b0, 2'b00};
                    end else if (bump_left && bump_right) begin
                        // Bumped both sides, switch from current (walking right → left)
                        next_state = {1'b0, 2'b00};
                    end
                end
            end

            2'b10: begin // Falling
                // While falling, ignore bumps and dig
                // Only thing: when ground reappears, resume walking in same direction
                if (ground) begin
                    // Resume walking in the direction we were falling from
                    // state[2] holds that direction
                    if (state[2]) begin
                        next_state = {state[2], 2'b01}; // walking right
                    end else begin
                        next_state = {state[2], 2'b00}; // walking left
                    end
                end
                // While falling, stay falling until ground reappears
            end

            2'b11: begin // Digging on ground
                if (!ground) begin
                    // Reached other side, fall down (keep direction)
                    next_state = {state[2], 2'b10};
                end else if (!dig) begin
                    // Stop digging, resume walking in same direction
                    if (state[2]) begin
                        next_state = {state[2], 2'b01}; // walking right
                    end else begin
                        next_state = {state[2], 2'b00}; // walking left
                    end
                end
                // While digging on ground, ignore bumps
            end
        endcase
    end

endmodule

