module TopModule (
    input  clk,
    input  reset,
    input  in,
    output reg done
);

// ------------------------------------------------------------
// State encoding
// ------------------------------------------------------------
typedef enum logic [2:0] {
    IDLE       = 3'd0,   // waiting for a start bit (line at 1)
    START      = 3'd1,   // sampled start bit (must be 0)
    DATA       = 3'd2,   // receiving 8 data bits (LSB first)
    STOP       = 3'd3,   // sampling stop bit (must be 1)
    ERROR      = 3'd4    // stop bit was not 1; return to IDLE
} state_t;

// ------------------------------------------------------------
// Internal signals
// ------------------------------------------------------------
state_t   state, next_state;
reg [7:0]  data_reg;   // holds the assembled 8-bit value
reg [3:0]  bit_cnt;    // 0..7 for data bits, 8 for stop bit check
reg        start_edge; // edge detector for the falling start bit
reg        in_reg1;    // delayed input for edge detection

// ------------------------------------------------------------
// State flip-flops (positive-edge triggered, active-high reset)
// ------------------------------------------------------------
always_ff @(posedge clk or posedge reset) begin
    if (reset)
        state <= IDLE;
    else
        state <= next_state;
end

// ------------------------------------------------------------
// Next-state logic (combinational)
// ------------------------------------------------------------
always_comb begin
    next_state = state;   // default: stay in current state
    done       = 1'b0;    // default: not asserted

    case (state)
        IDLE: begin
            // Look for a falling edge (1 -> 0) on the line.
            if (start_edge)
                next_state = START;
        end

        START: begin
            // After confirming the start bit (0), move to data phase.
            next_state = DATA;
        end

        DATA: begin
            // Shift in the incoming bit LSB-first.
            if (bit_cnt == 4'd7) begin
                // Last data bit sampled; now check the stop bit.
                next_state = STOP;
            end else begin
                // Continue shifting.
                next_state = DATA;
            end
        end

        STOP: begin
            // Verify the stop bit is 1.
            if (in_reg1 == 1'b1) begin
                // Correct stop bit: indicate reception complete.
                done   = 1'b1;
                next_state = IDLE;
            end else begin
                // Stop bit was not 1 -> error.
                next_state = ERROR;
            end
        end

        ERROR: begin
            // Idle until a new start bit appears.
            if (start_edge)
                next_state = START;
        end

        default: next_state = IDLE;
    endcase
end

// ------------------------------------------------------------
// Output / shift-register logic
// ------------------------------------------------------------
always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
        bit_cnt <= 4'd0;
        data_reg <= 8'd0;
    end else begin
        case (state)
            IDLE: begin
                bit_cnt <= 4'd0;
                data_reg <= 8'd0;
            end

            START: begin
                // Reset bit counter; first data bit will be sampled next cycle.
                bit_cnt <= 4'd0;
            end

            DATA: begin
                // Shift the new bit into the LSB of data_reg.
                // in is the bit received (LSB first).
                data_reg <= {in, data_reg[7:1]};
                // Increment bit counter.
                bit_cnt <= bit_cnt + 4'd1;
            end

            STOP: begin
                // State leaves on the next clock edge (handled by
                // state flip-flops). No additional logic needed here
                // except the 'done' flag which is set in the
                // next-state block.
            end

            ERROR: begin
                // Return to IDLE on next clock; counters reset in IDLE.
            end

            default: begin
                bit_cnt <= 4'd0;
                data_reg <= 8'd0;
            end
        endcase
    end
end

// ------------------------------------------------------------
// Start-bit edge detector
// ------------------------------------------------------------
// We detect the transition 1 -> 0 on the input line.
// start_edge is pulsed high for one clock cycle after the falling
// edge occurs. This synchronises the FSM to the actual bit period.
always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
        start_edge <= 1'b0;
        in_reg1    <= 1'b1; // assume idle high
    end else begin
        in_reg1    <= in;
        // falling edge: previous was 1, current is 0
        if (in_reg1 && (!in))
            start_edge <= 1'b1;
        else
            start_edge <= 1'b0;
    end
end

endmodule

