            if (train_taken) begin
                if (pht[train_index] < 2'b11) pht[train_index] <= pht[train_index] + 1;
            end else begin
                if (pht[train_index] > 2'b00) pht[train_index] <= pht[train_index] - 1;
            end
        end
    end

    // Global History Register update
    // Training takes precedence over prediction if both occur
    // If mispredicted, recover GHR to state after mispredicting branch
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            ghr <= 7'b0;
        end else begin
