module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    output walk_left,
    output walk_right,
    output aaah
);

    // State encoding
    typedef enum logic [1:0] {
        WALK_LEFT  = 2'b00,
        WALK_RIGHT = 2'b01
    } state_t;

    // Sequential logic: state flip-flops
    state_t state, next_state;

    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WALK_LEFT;
        end else begin
            state <= next_state;
        end
    end

    // Next-state logic
    always_comb begin
        // Default: stay in current state
        next_state = state;

        // Priority: ground=0 (falling) first, then bump logic
        if (!ground) begin
            // Falling: state does not change
            // aaah is asserted during falling
        end else begin
            // Not falling: evaluate bumps
            // If bumped on both sides or one side, switch direction
            if (bump_left && bump_right) begin
                // Bumped both sides: switch direction
                if (state == WALK_LEFT)
                    next_state <= WALK_RIGHT;
                else
                    next_state <= WALK_LEFT;
            end else if (bump_left) begin
                // Bumped left: walk right
                next_state <= WALK_RIGHT;
            end else if (bump_right) begin
                // Bumped right: walk left
                next_state <= WALK_LEFT;
            }
            // else: no bump, stay in current state (already defaulted)
        end
    end

    // Output logic (Moore machine): outputs depend only on current state
    assign walk_left  = (state == WALK_LEFT);
    assign walk_right = (state == WALK_RIGHT);
    assign aaah       = !ground;  // aaah is 1 when ground=0 (falling)

endmodule

