module TopModule (
    input  clk,
    input  enable,
    input  S,
    input  A,
    input  B,
    input  C,
    output Z
);

    // Internal regs for the 8 flip-flop outputs
    // Q[0] is the MSB (input side), Q[7] is the LSB (output side)
    reg [7:0] Q;

    // Instantiate 8 D-type flip-flops to form the shift register
    dff_r reg0 (.clk(clk), .din(S), .dout(Q[0]), .en(enable));
    dff_r reg1 (.clk(clk), .din(Q[0]), .dout(Q[1]), .en(enable));
    dff_r reg2 (.clk(clk), .din(Q[1]), .dout(Q[2]), .en(enable));
    dff_r reg3 (.clk(clk), .din(Q[2]), .dout(Q[3]), .en(enable));
    dff_r reg4 (.clk(clk), .din(Q[3]), .dout(Q[4]), .en(enable));
    dff_r reg5 (.clk(clk), .din(Q[4]), .dout(Q[5]), .en(enable));
    dff_r reg6 (.clk(clk), .din(Q[5]), .dout(Q[6]), .en(enable));
    dff_r reg7 (.clk(clk), .din(Q[6]), .dout(Q[7]), .en(enable));

    // 8-to-1 multiplexer: selects Q[index] based on address lines A, B, C
    // ABC = 000 -> Q[0], 001 -> Q[1], ..., 111 -> Q[7]
    // Index = A*4 + B*2 + C*1
    assign Z = (A & B & C) ? Q[7] :
               (A & B & ~C) ? Q[6] :
               (A & ~B & C) ? Q[5] :
               (A & ~B & ~C) ? Q[4] :
               (~A & B & C) ? Q[3] :
               (~A & B & ~C) ? Q[2] :
               (~A & ~B & C) ? Q[1] :
                              Q[0];

endmodule

// Simple positive-edge-triggered D flip-flop with synchronous enable
module dff_r (
    input  clk,
    input  din,
    output dout,
    input  en
);
    always_ff @(posedge clk) begin
        if (en)
            dout <= din;
    end
endmodule

