module TopModule (
    input  logic clk,
    input  logic load,
    input  logic [511:0] data,
    output logic [511:0] q
);

    // Internal register to hold the current state
    logic [511:0] state;

    // A function to compute Rule 110 next state for a single cell
    function automatic logic rule110_next;
        input logic L, C, R;
        // Minterms for Rule 110 where next state is 1:
        // 110, 101, 011, 010, 001
        rule110_next = (L & C & ~R) | (L & ~C & R) | (~L & C & R) | (~L & C & ~R) | (~L & ~C & R);
    endfunction

    // Combinational logic to compute the next state according to Rule 110
    always_comb begin
        // Cell 0: left neighbour is 0, centre is state[0], right neighbour is state[1]
        next_state[0] = rule110_next(1'b0, state[0], state[1]);

        // Cells 1 to 510
        for (genvar i = 1; i < 511; i = i + 1) begin : rule110_loop
            next_state[i] = rule110_next(state[i-1], state[i], state[i+1]);
        end

        // Cell 511: left neighbour is state[510], centre is state[511], right neighbour is 0
        next_state[511] = rule110_next(state[510], state[511], 1'b0);
    end

    // Register for the state and output
    always_ff @(posedge clk) begin
        if (load)
            state <= data;
        else
            state <= next_state;
    end

    // Output q follows the state
    assign q = state;

endmodule

