module TopModule (
    input  logic        clk,
    input  logic        load,
    input  logic [255:0] data,
    output logic [255:0] q
);

    // Internal register to hold the current 16x16 grid state
    logic [255:0] grid;

    // ------------------------------------------------------------
    // Combinational logic: compute next state based on current grid
    // ------------------------------------------------------------
    always_comb begin
        logic [255:0] next_grid;
        integer       r, c, nr, nc, count;

        // Iterate over every cell (row r, column c)
        for (r = 0; r < 16; r = r + 1) begin
            for (c = 0; c < 16; c = c + 1) begin
                // Flatten index for the current cell in the 256-bit vector
                int cur_idx = r * 16 + c;
                logic [8:0] alive_neighbours = 9'b0; // enough for max 8

                // Examine the 8 Moore neighbours with toroidal wrap‑around
                for (nr = -1; nr <= 1; nr = nr + 1) begin
                    for (nc = -1; nc <= 1; nc = nc + 1) begin
                        // Skip the cell itself
                        if (nr == 0 && nc == 0) continue;

                        // Compute wrapped row and column indices
                        int wr = (r + nr + 16) % 16;
                        int wc = (c + nc + 16) % 16;

                        // Flatten index of the neighbour
                        int n_idx = wr * 16 + wc;

                        // Add neighbour state (1 or 0)
                        alive_neighbours = alive_neighbours + grid[n_idx];
                    end
                end

                // Apply Game of Life rules
                if (alive_neighbours == 3) begin
                    // Rule (3): exactly 3 neighbours -> becomes 1
                    next_grid[cur_idx] = 1'b1;
                end else if (alive_neighbours == 2) begin
                    // Rule (2): 2 neighbours -> state stays unchanged
                    next_grid[cur_idx] = grid[cur_idx];
                end else begin
                    // Rule (1) and (4): 0‑1 or 4+ neighbours -> becomes 0
                    next_grid[cur_idx] = 1'b0;
                end
            end
        end

        // If load is active, feed the provided data; otherwise use computed next state
        if (load)
            grid = data;
        else
            grid = next_grid;
    end

    // ------------------------------------------------------------
    // Sequential logic: update q on the positive edge of clk
    // ------------------------------------------------------------
    always_ff @(posedge clk) begin
        q <= grid;
    end

endmodule

