module TopModule (
    input  clk,
    input  x,
    input  [2:0] y,
    output Y0,
    output z
);

    // Internal wire to hold the computed next state Y[2:0]
    logic [2:0] Y_next;

    // ==========================================
    // Next State Logic (Combinational)
    // ==========================================
    always_comb begin
        case (y)
            3'b000: begin
                Y_next = (x == 1'b0) ? 3'b000 : 3'b001;
            end
            3'b001: begin
                Y_next = (x == 1'b0) ? 3'b001 : 3'b100;
            end
            3'b010: begin
                Y_next = (x == 1'b0) ? 3'b010 : 3'b001;
            end
            3'b011: begin
                Y_next = (x == 1'b0) ? 3'b001 : 3'b010;
            end
            3'b100: begin
                Y_next = (x == 1'b0) ? 3'b011 : 3'b100;
            end
            default: begin
                Y_next = 3'bxxx; // Undefined state
            end
        endcase
    end

    // ==========================================
    // Output Logic
    // ==========================================
    // "Note that the output Y0 is Y[0] of the next state signal."
    assign Y0 = Y_next[0];

    // Output z based on the present state (y) per the specification table.
    always_comb begin
        case (y)
            3'b000: z = 1'b0;
            3'b001: z = 1'b0;
            3'b010: z = 1'b0;
            3'b011: z = 1'b1;
            3'b100: z = 1'b1;
            default: z = 1'b0; // Default assignment for undefined states
        endcase
    end

    // ==========================================
    // State Register (Optional but typical for FSM)
    // The specification requests "next state logic". 
    // To make this a functional sequential FSM, the next state is 
    // typically registered. 
    // 
    // If the intention is that 'y' is the present state input for 
    // the current cycle, and the module produces the next state 
    // for the following cycle, we register Y_next. 
    // Note: The 'y' input itself is not typically registered back 
    // into the state logic in a way that overrides the table's 
    // present state definition without a clear reset/set, but 
    // standard FSM practice often registers the state.
    // 
    // Here we register the next state into an internal register 
    // to demonstrate the sequential behavior, assuming the system 
    // provides the present state 'y' externally or this module 
    // can be viewed as having an internal state register 'state_reg' 
    // that updates on the clock. 
    //
    // If the user expects 'y' to be the state output, they would 
    // connect this module's internal state to 'y'. Given the ports, 
    // we register the computed next state.
    //
    logic [2:0] state_reg;

    always_ff @(posedge clk) begin
        // The present state for the next cycle is computed as Y_next.
        state_reg <= Y_next;
    end

endmodule

